<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import type {PcApi} from '../api';
import type {SourceBatch,MasterPage,ManufacturerMaster,CatalogVariant,ParsingJob} from '../../../../packages/contracts/src';
import {SourceBatchDraft,emptySourceRow,sourceFields,isDenied,assertPreviewToken} from '../../../../packages/master-client/src';
import SourceFiles from './SourceFiles.vue';
type Submit=<T>(label:string,path:string,body:Record<string,unknown>)=>Promise<T>;
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'>;userId:string;readonly?:boolean;locked?:boolean;pending?:boolean;submit?:Submit;itemVariant?:CatalogVariant}>(),emit=defineEmits<{(e:'busy-changed',v:boolean):void;(e:'failure',v:unknown):void}>();
const busy=ref(false),childBusy=ref(false),error=ref(''),notice=ref(''),page=ref(1),pageSize=25,batches=ref<SourceBatch[]>([]),total=ref<number|null>(null),detail=ref<SourceBatch|null>(null),creating=ref(false),dirty=ref(false),review=ref<'confirm'|'void'|null>(null),ack=ref(false),voidReason=ref(''),detailPage=ref(1),snapshotPage=ref(1),manualPage=ref(1),previewPage=ref(1),rawPage=ref(1),showSnapshot=ref(false),draft=reactive(new SourceBatchDraft(()=>!!props.readonly)),manufacturerKeyword=ref(''),manufacturers=ref<ManufacturerMaster[]>([]),catalogKeyword=ref(''),catalog=ref<CatalogVariant[]>([]),detailSourceRef=ref<InstanceType<typeof SourceFiles>|null>(null),sourceRef=ref<InstanceType<typeof SourceFiles>|null>(null),headerRow=ref(1);
const filter=reactive({manufacturerId:'',batchNo:'',sourceBatchNo:'',quotedFrom:'',quotedTo:''}),meta=reactive({manufacturerId:'',sourceBatchNo:'',quotedAt:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),sourceFileId:'',sourceType:'manual' as 'manual'|'excel'});
let disposed=false,epoch=0;
const locked=computed(()=>!!props.locked||busy.value||childBusy.value),writeLocked=computed(()=>locked.value||!!props.readonly||!!props.pending||!!review.value),navigationLocked=computed(()=>locked.value||dirty.value||!!review.value||!!props.pending),files=computed(()=>sourceRef.value?.sourceFiles||[]),parsedJob=computed(()=>(sourceRef.value as any)?.parsedJob as ParsingJob|undefined),columns=computed(()=>Math.max(1,...draft.rawRows.map(r=>r.cells.length))),header=computed(()=>draft.rawRows.find(r=>r.rowNumber===headerRow.value)?.cells||[]),savedColumns=computed(()=>[...new Set((detail.value?.previewSnapshot.rawRows||[]).flatMap(r=>Object.keys(r)))]),detailRows=computed(()=>(detail.value?.rows||[]).filter(r=>!props.itemVariant||r.itemVariantId===props.itemVariant.variantId)),visibleRows=computed(()=>draft.rows.slice((manualPage.value-1)*25,manualPage.value*25)),visiblePreview=computed(()=>draft.preview?.rows.slice((previewPage.value-1)*25,previewPage.value*25)||[]),manufacturerName=(id:string,actualName?:string)=>actualName||manufacturers.value.find(m=>m.id===id)?.name||'厂家记录';
watch(()=>busy.value||childBusy.value||dirty.value||!!review.value||!!props.pending,v=>emit('busy-changed',v),{immediate:true,flush:'sync'});
watch(()=>JSON.stringify([meta,draft.rows,draft.mapping]),()=>{if(creating.value){draft.invalidate();review.value=null;ack.value=false;dirty.value=true;}},{flush:'sync'});
watch(()=>review.value,()=>{ack.value=false;});
watch(()=>meta.manufacturerId,()=>{if(creating.value){meta.sourceFileId='';draft.rawRows=[];draft.invalidate();}});
function clearPrivate(){batches.value=[];detail.value=null;manufacturers.value=[];catalog.value=[];creating.value=false;draft.rows=[emptySourceRow()];draft.rawRows=[];draft.invalidate();review.value=null;dirty.value=false;}
async function run(work:()=>Promise<void>){if(busy.value||disposed)return;const turn=++epoch;busy.value=true;error.value='';notice.value='';try{await work();}catch(e){if(!disposed&&turn===epoch){error.value=e instanceof Error?e.message:'来源资料操作失败。';if(isDenied(e))clearPrivate();if(['VERSION_CONFLICT','PREVIEW_EXPIRED','PREVIEW_INVALID'].includes((e as any)?.code)){draft.rejectPreview(e);review.value=null;}emit('failure',e);}}finally{if(!disposed&&turn===epoch)busy.value=false;}}
async function loadManufacturers(){const q=new URLSearchParams({keyword:manufacturerKeyword.value,includeInactive:'true',page:'1',pageSize:'100'});const r=await props.api.get<MasterPage>('/admin/master-data/manufacturers?'+q);manufacturers.value=r.items as ManufacturerMaster[];}
async function loadList(next=page.value){const q=new URLSearchParams({page:String(Math.max(1,Math.min(10000,next))),pageSize:String(pageSize)});if(props.itemVariant)q.set('itemVariantId',props.itemVariant.variantId);for(const [k,v] of Object.entries(filter))if(v)q.set(k,v);const r=await props.api.get<{items:SourceBatch[];total?:number}>('/source-batches?'+q);if(!Array.isArray(r.items))throw new Error('来源批次列表无法核实。');batches.value=r.items;page.value=next;total.value=r.total??null;}
async function refresh(){if(navigationLocked.value)return;await run(async()=>{await loadManufacturers();if(detail.value)detail.value=await props.api.get('/source-batches/'+detail.value.id);else await loadList();});}
async function open(id:string){if(navigationLocked.value)return;await run(async()=>{detail.value=await props.api.get<SourceBatch>('/source-batches/'+encodeURIComponent(id));detailPage.value=1;snapshotPage.value=1;showSnapshot.value=false;});}
function start(){if(writeLocked.value||dirty.value)return;detail.value=null;draft.rows=[emptySourceRow()];draft.rawRows=[];draft.mapping={rawItemName:'rawItemName',referencePrice:'referencePrice',specification:'specification',origin:'origin',grade:'grade',unit:'unit',itemVariantId:'itemVariantId',remark:'remark'};draft.invalidate();meta.manufacturerId='';meta.sourceBatchNo='';meta.sourceFileId='';meta.sourceType='manual';creating.value=true;dirty.value=true;manualPage.value=1;}
function discard(){if(locked.value||props.pending||sourceRef.value?.canLeave()===false)return;creating.value=false;dirty.value=false;review.value=null;draft.invalidate();voidReason.value='';}
function addRow(){if(writeLocked.value)return;if(draft.rows.length>=1000){error.value='每个来源批次最多 1000 行。';return;}draft.rows.push(emptySourceRow());manualPage.value=Math.ceil(draft.rows.length/25);}
function removeRow(index:number){if(writeLocked.value||draft.rows.length<=1)return;draft.rows.splice(index,1);manualPage.value=Math.min(manualPage.value,Math.ceil(draft.rows.length/25));}
function setType(){draft.rows=[emptySourceRow()];draft.rawRows=[];draft.mapping={rawItemName:'rawItemName',referencePrice:'referencePrice',specification:'specification',origin:'origin',grade:'grade',unit:'unit',itemVariantId:'itemVariantId',remark:'remark'};manualPage.value=1;}
function useParsed(){if(writeLocked.value)return;try{const job=parsedJob.value;if(!job||job.status!=='succeeded'||!job.rawRows)throw new Error('请先在原始资料中解析文件，并载入成功的解析记录。');if(meta.sourceFileId&&meta.sourceFileId!==job.fileId)throw new Error('所选原始文件与当前解析记录不一致。');meta.sourceFileId=job.fileId;draft.useParsed(job.rawRows,Number(headerRow.value));manualPage.value=1;rawPage.value=1;notice.value='原始单元格已载入。请按表头映射字段，再逐行校对预览。';}catch(e){error.value=(e as Error).message;}}
async function searchCatalog(){if(locked.value)return;await run(async()=>{catalog.value=(await props.api.get<{items:CatalogVariant[]}>('/catalog/variants?keyword='+encodeURIComponent(catalogKeyword.value)+'&limit=100')).items;});}
async function preview(){if(writeLocked.value)return;await run(async()=>{const body=draft.previewBody({...meta,sourceFileId:meta.sourceFileId||null});const result=await props.api.post<import('../../../../packages/contracts/src').SourceBatchPreview>('/admin/source-batches/preview',body);assertPreviewToken(result.previewToken);draft.preview=result;draft.selected=[];draft.reviewed=[];previewPage.value=1;notice.value='预览 15 分钟有效；请逐行核对并显式选择。改动资料后须重新预览。';});}
function editMapped(index:number,field:typeof sourceFields[number]['key'],value:string){if(writeLocked.value)return;try{draft.setMappedCell(index,field,value);}catch(e){error.value=(e as Error).message;}}
function select(row:number,checked:boolean,explicit=false){if(writeLocked.value)return;try{draft.select(row,checked,explicit);error.value='';}catch(e){error.value=(e as Error).message;}}
function reviewConfirm(){if(writeLocked.value)return;try{draft.confirmBody();review.value='confirm';}catch(e){error.value=(e as Error).message;}}
async function commit(){if(locked.value||props.readonly||props.pending||!ack.value||!props.submit||!review.value)return;const action=review.value;await run(async()=>{if(action==='confirm'){const body=draft.confirmBody();const result=await props.submit!<SourceBatch>('确认厂家来源批次','/admin/source-batches/confirm',body);creating.value=false;dirty.value=false;draft.invalidate();detail.value=result;}else{if(!detail.value||!voidReason.value.trim())throw new Error('请填写整批作废原因。');detail.value=await props.submit!<SourceBatch>('整批作废来源资料','/admin/source-batches/'+detail.value.id+'/void',{expectedVersion:detail.value.version,reason:voidReason.value.trim()});dirty.value=false;}review.value=null;notice.value='来源批次已保存；仅资料参考，不参与本次报价。';await loadList(1);});}
function askVoid(){if(writeLocked.value||!detail.value)return;if(!voidReason.value.trim()||voidReason.value.trim().length>500){error.value='请填写 1–500 字整批作废原因。';return;}review.value='void';dirty.value=true;}
async function afterRecovery(){creating.value=false;detail.value=null;dirty.value=false;review.value=null;draft.invalidate();await run(()=>loadList(1));}
function canLeave(){return !busy.value&&!childBusy.value&&!dirty.value&&!review.value&&!props.pending&&(sourceRef.value?.canLeave()??true);}
defineExpose({refresh,canLeave,afterRecovery});
onMounted(()=>void run(async()=>{await loadManufacturers();await loadList(1);}));onBeforeUnmount(()=>{disposed=true;epoch++;emit('busy-changed',false);});
</script>
<template>
 <section class="source-batches"><div class="source-top"><div><h2>厂家全品类来源批次</h2><p class="reference-notice">仅资料参考，不参与本次报价</p><p class="muted">每次手工录入或导入创建独立批次。确认后的批次与原始校对依据永久保留，只能整体作废。</p></div><button v-if="!readonly&&!creating&&!detail" class="primary" :disabled="writeLocked" @click="start">新建来源批次</button></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="filter-note" role="status">{{notice}}</p><p v-if="busy" role="status">正在读取或提交来源资料…</p><p v-if="readonly" class="muted">全量来源资料只读查阅；来源价不会填入本次询价或销售计价。</p>
 <div v-if="creating||detail" class="button-row"><button :disabled="navigationLocked" @click="detail=null">← 批次列表</button><button v-if="creating||dirty||review" :disabled="locked||pending" @click="discard">放弃本次未提交修改</button></div>
 <template v-if="!creating&&!detail"><form class="source-filters" @submit.prevent="run(()=>loadList(1))"><label>厂家名称<input v-model="manufacturerKeyword" maxlength="100" :disabled="navigationLocked" placeholder="输入后查找厂家"/></label><button :disabled="navigationLocked" type="button" @click="run(loadManufacturers)">查找厂家</button><label>归属厂家<select v-model="filter.manufacturerId" :disabled="navigationLocked"><option value="">全部厂家</option><option v-for="m in manufacturers" :key="m.id" :value="m.id">{{m.name}}{{m.active?'':'（已停用）'}}</option></select></label><label>系统批次号<input v-model="filter.batchNo" maxlength="100" :disabled="navigationLocked"/></label><label>厂家原始批次号<input v-model="filter.sourceBatchNo" maxlength="100" :disabled="navigationLocked"/></label><label>报价日期从<input v-model="filter.quotedFrom" type="date" :disabled="navigationLocked"/></label><label>报价日期至<input v-model="filter.quotedTo" type="date" :disabled="navigationLocked"/></label><button class="primary" :disabled="navigationLocked">查询批次</button></form><div class="table-scroll"><table><thead><tr><th>系统批次号 / 厂家</th><th>厂家原始批次号</th><th>报价日期 / 来源</th><th>已确认行 / 原总行</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="b in batches" :key="b.id"><td><strong>{{b.batchNo}}</strong><small>{{manufacturerName(b.manufacturerId,b.manufacturerName)}}</small></td><td>{{b.sourceBatchNo||'未填写'}}</td><td>{{b.quotedAt.slice(0,10)}}<small>{{b.sourceType==='manual'?'手工录入':'表格导入'}}</small></td><td>{{b.validRows}} / {{b.totalRows}}</td><td>{{b.status==='confirmed'?'已确认':'整批已作废'}}</td><td><button :disabled="navigationLocked" @click="open(b.id)">查看详情 →</button></td></tr><tr v-if="!busy&&!batches.length"><td colspan="6" class="empty">本页暂无来源批次。</td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} 页 · 每页 {{pageSize}} 条{{total===null?'':' · 共 '+total+' 条'}}</span><button :disabled="navigationLocked||page<=1" @click="run(()=>loadList(page-1))">上一页</button><button :disabled="navigationLocked||page>=10000||batches.length<pageSize" @click="run(()=>loadList(page+1))">下一页</button></div></template>
 <template v-if="creating"><h3>录入与原始依据</h3><div class="form-grid"><label>查找厂家<input v-model="manufacturerKeyword" maxlength="100" :disabled="writeLocked"/></label><button :disabled="writeLocked" @click="run(loadManufacturers)">查找厂家（最多 100 条）</button><label>归属厂家 *<select v-model="meta.manufacturerId" :disabled="writeLocked||!!sourceRef&&childBusy"><option value="">请选择启用厂家</option><option v-for="m in manufacturers.filter(m=>m.active)" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>厂家原始批次号<input v-model="meta.sourceBatchNo" maxlength="100" :disabled="writeLocked"/></label><label>来源报价日期 *<input v-model="meta.quotedAt" type="date" :disabled="writeLocked"/></label><label>录入方式<select v-model="meta.sourceType" :disabled="writeLocked" @change="setType"><option value="manual">手工逐行录入</option><option value="excel">Excel / XLS / CSV 导入</option></select></label></div>
 <div v-if="meta.manufacturerId" class="source-file-panel"><SourceFiles ref="sourceRef" :api="api" :user-id="userId" :reference="{kind:'manufacturer',manufacturerId:meta.manufacturerId}" mode="excel" :locked="!!props.locked||busy||!!props.pending||!!review" @busy-changed="childBusy=$event" @failure="emit('failure',$event)"/><label>本批原始文件（可选）<select v-model="meta.sourceFileId" :disabled="writeLocked"><option value="">未关联文件</option><option v-for="f in files" :key="f.id" :value="f.id">{{f.fileName}}</option></select></label></div><p v-else class="filter-note">先选择厂家，再上传或选择该厂家的原始来源文件。</p>
 <template v-if="meta.sourceType==='excel'"><div class="button-row"><label>表头行号（0 表示无表头）<input v-model.number="headerRow" type="number" min="0" max="1001" :disabled="writeLocked"/></label><button :disabled="writeLocked||!parsedJob?.rawRows" @click="useParsed">载入当前解析原文</button></div><p class="muted">先在原始资料中解析并刷新成功记录。表头仅作字段选择依据，数据行仍逐行核对，最多 1000 行。</p><div v-if="draft.rawRows.length" class="table-scroll raw-grid"><table><thead><tr><th>原行号</th><th v-for="n in columns" :key="n">第 {{n}} 列</th><th>解析问题</th></tr></thead><tbody><tr v-for="r in draft.rawRows.slice((rawPage-1)*25,rawPage*25)" :key="r.rowNumber"><td>{{r.rowNumber}}</td><td v-for="n in columns" :key="n">{{r.cells[n-1]||'—'}}</td><td>{{r.errors.join('；')||'—'}}</td></tr></tbody></table></div><div v-if="draft.rawRows.length" class="pagination"><button :disabled="rawPage<=1" @click="rawPage--">原文上一页</button><span>{{rawPage}} / {{Math.ceil(draft.rawRows.length/25)}}</span><button :disabled="rawPage*25>=draft.rawRows.length" @click="rawPage++">原文下一页</button></div><div v-if="draft.rawRows.length" class="mapping-grid"><label v-for="field in sourceFields" :key="field.key">{{field.label}}{{field.required?' *':''}}<select v-model="draft.mapping[field.key]" :disabled="writeLocked"><option value="">{{field.required?'请选择列':'不使用'}}</option><option v-for="n in columns" :key="n" :value="'c'+(n-1)">第 {{n}} 列{{header[n-1]?' · '+header[n-1]:''}}</option></select></label></div></template>
 <template v-else><div class="button-row"><label>规格匹配关键词<input v-model="catalogKeyword" maxlength="100" :disabled="writeLocked" placeholder="品名或规格"/></label><button :disabled="writeLocked" @click="searchCatalog">查找标准规格（最多 100 条）</button><button :disabled="writeLocked||draft.rows.length>=1000" @click="addRow">增加一行</button><span>当前 {{draft.rows.length}} / 1000 行</span></div><div class="table-scroll manual-grid"><table><thead><tr><th>行</th><th>来源品名 *</th><th>参考价 / 元·kg *</th><th>规格 / 产地 / 等级</th><th>关联标准规格</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="(r,index) in visibleRows" :key="(manualPage-1)*25+index"><td>{{(manualPage-1)*25+index+1}}</td><td><input v-model="r.rawItemName" maxlength="100" :disabled="writeLocked" aria-label="来源品名"/></td><td><input v-model="r.referencePrice" inputmode="decimal" :disabled="writeLocked" aria-label="来源参考价"/><small>单位固定 kg</small></td><td><input v-model="r.specification" placeholder="规格" maxlength="200" :disabled="writeLocked" aria-label="来源规格"/><input v-model="r.origin" placeholder="产地" maxlength="200" :disabled="writeLocked" aria-label="来源产地"/><input v-model="r.grade" placeholder="等级" maxlength="200" :disabled="writeLocked" aria-label="来源等级"/></td><td><select v-model="r.itemVariantId" :disabled="writeLocked" aria-label="关联标准规格"><option value="">未匹配（确认时逐行核对）</option><option v-if="r.itemVariantId&&!catalog.some(c=>c.variantId===r.itemVariantId)" :value="r.itemVariantId">已选规格（可保留或重新搜索）</option><option v-for="c in catalog" :key="c.variantId" :value="c.variantId">{{c.name}} · {{c.specification||'常用规格'}} · {{c.origin}} {{c.grade}}</option></select></td><td><input v-model="r.remark" maxlength="500" :disabled="writeLocked" aria-label="来源备注"/></td><td><button :disabled="writeLocked||draft.rows.length<=1" @click="removeRow((manualPage-1)*25+index)">移除此草稿行</button></td></tr></tbody></table></div><div class="pagination"><button :disabled="locked||manualPage<=1" @click="manualPage--">上一页</button><span>第 {{manualPage}} / {{Math.ceil(draft.rows.length/25)}} 页</span><button :disabled="locked||manualPage*25>=draft.rows.length" @click="manualPage++">下一页</button></div></template>
 <section v-if="meta.sourceType==='excel'&&draft.rawRows.length"><h3>导入行人工校对与商品匹配</h3><p class="muted">表头映射后可直接改正下列数据行；上方原始单元格与原文件继续保留。未映射的可选字段可在此补填。</p><div class="button-row"><label>规格匹配关键词<input v-model="catalogKeyword" maxlength="100" :disabled="writeLocked"/></label><button :disabled="writeLocked" @click="searchCatalog">查找标准规格（最多 100 条）</button></div><div class="table-scroll manual-grid"><table><thead><tr><th>数据行</th><th v-for="field in sourceFields" :key="field.key">{{field.label}}</th></tr></thead><tbody><tr v-for="(_r,index) in visibleRows" :key="(manualPage-1)*25+index"><td>{{(manualPage-1)*25+index+1}}</td><td v-for="field in sourceFields" :key="field.key"><select v-if="field.key==='itemVariantId'" :value="draft.mappedCell((manualPage-1)*25+index,field.key)" :disabled="writeLocked" @change="editMapped((manualPage-1)*25+index,field.key,($event.target as HTMLSelectElement).value)"><option value="">未匹配</option><option v-if="draft.mappedCell((manualPage-1)*25+index,field.key)&&!catalog.some(c=>c.variantId===draft.mappedCell((manualPage-1)*25+index,field.key))" :value="draft.mappedCell((manualPage-1)*25+index,field.key)">原表已关联规格（可保留或重新选择）</option><option v-for="c in catalog" :key="c.variantId" :value="c.variantId">{{c.name}} · {{c.specification||'常用规格'}} · {{c.origin}} {{c.grade}}</option></select><input v-else :value="draft.mappedCell((manualPage-1)*25+index,field.key)" :aria-label="field.label" :disabled="writeLocked" :placeholder="field.key==='unit'?'未填按 kg':''" :maxlength="field.key==='remark'?500:field.key==='rawItemName'?100:200" @input="editMapped((manualPage-1)*25+index,field.key,($event.target as HTMLInputElement).value)"/></td></tr></tbody></table></div><div class="pagination"><button :disabled="locked||manualPage<=1" @click="manualPage--">上一页</button><span>{{manualPage}} / {{Math.ceil(draft.rows.length/25)}}</span><button :disabled="locked||manualPage*25>=draft.rows.length" @click="manualPage++">下一页</button></div></section>
 <button class="primary" :disabled="writeLocked||meta.sourceType==='excel'&&!draft.rawRows.length" @click="preview">生成服务端校对预览</button>
 <section v-if="draft.preview" class="batch-preview"><h3>预览与确认范围</h3><p>原始 {{draft.preview.totalRows}} 行 · 可核对 {{draft.preview.validRows}} 行 · 异常 {{draft.preview.invalidRows}} 行 · 已选 {{draft.selected.length}} 行。预览 15 分钟有效。</p><p class="filter-note">异常行不能确认；未匹配或重复行需逐行点击“已核对，纳入”。未选行及原始依据随批次保存。</p><div class="table-scroll"><table><thead><tr><th>确认范围</th><th>行 / 状态</th><th>来源品名 / 规格</th><th>产地 / 等级</th><th>来源参考价</th><th>说明与问题</th></tr></thead><tbody><tr v-for="r in visiblePreview" :key="r.rowNumber"><td><input v-if="r.status==='valid'" type="checkbox" :checked="draft.selected.includes(r.rowNumber)" :disabled="writeLocked" @change="select(r.rowNumber,($event.target as HTMLInputElement).checked)" aria-label="纳入确认"/><button v-else-if="r.status!=='invalid'" :disabled="writeLocked" @click="select(r.rowNumber,!draft.selected.includes(r.rowNumber),true)">{{draft.selected.includes(r.rowNumber)?'已核对纳入 · 取消':'已核对，纳入'}}</button><span v-else>须修正后重做预览</span></td><td>{{r.rowNumber}} · {{({valid:'已匹配',unmatched:'未匹配',duplicate:'疑似重复',invalid:'异常'})[r.status]}}</td><td>{{r.rawItemName}}<small>{{r.specification||'—'}}</small></td><td>{{r.origin||'—'}}<small>{{r.grade||'—'}}</small></td><td>{{r.referencePrice}} / {{r.unit}}</td><td class="error">{{r.errors.join('；')||r.remark||'—'}}</td></tr></tbody></table></div><div class="pagination"><button :disabled="previewPage<=1||locked" @click="previewPage--">上一页</button><span>{{previewPage}} / {{Math.ceil(draft.preview.rows.length/25)}}</span><button :disabled="previewPage*25>=draft.preview.rows.length||locked" @click="previewPage++">下一页</button></div><button class="primary" :disabled="writeLocked||!draft.selected.length" @click="reviewConfirm">复核确认选中 {{draft.selected.length}} 行</button></section>
 </template>
 <template v-if="detail"><div class="detail-heading"><h3>{{detail.batchNo}}</h3><p>{{manufacturerName(detail.manufacturerId,detail.manufacturerName)}} · {{detail.quotedAt.slice(0,10)}} · {{detail.sourceType==='manual'?'手工录入':'表格导入'}} · {{detail.status==='confirmed'?'已确认':'整批已作废'}}</p><p>厂家原始批次号：{{detail.sourceBatchNo||'未填写'}} · 已确认 {{detail.rows.length}} 行 / 原始 {{detail.totalRows}} 行</p><p v-if="itemVariant" class="filter-note">当前规格已确认关联 {{detailRows.length}} 行；下表仅展示本规格。整批校对依据和原文件仍完整保留。</p><p v-if="detail.status==='voided'" class="error">整批作废原因：{{detail.voidReason}} · {{detail.voidedAt?.slice(0,19).replace('T',' ')}}</p></div><div class="table-scroll"><table><thead><tr><th>原行号</th><th>来源品名 / 规格</th><th>产地 / 等级</th><th>参考价 / 单位</th><th>匹配状态 / 备注</th></tr></thead><tbody><tr v-for="r in detailRows.slice((detailPage-1)*50,detailPage*50)" :key="r.rowNumber"><td>{{r.rowNumber}}</td><td>{{r.rawItemName}}<small>{{r.specification}}</small></td><td>{{r.origin||'—'}} / {{r.grade||'—'}}</td><td>{{r.referencePrice}} / {{r.unit}}</td><td>{{r.status==='valid'?'已关联标准规格':r.status==='duplicate'?'重复资料，已人工确认':'未匹配，已人工确认'}}<small>{{r.remark}}</small></td></tr></tbody></table></div><div class="pagination"><button :disabled="locked||detailPage<=1" @click="detailPage--">上一页</button><span>{{detailPage}} / {{Math.max(1,Math.ceil(detailRows.length/50))}}</span><button :disabled="locked||detailPage*50>=detailRows.length" @click="detailPage++">下一页</button></div><button :disabled="locked" @click="showSnapshot=!showSnapshot">{{showSnapshot?'收起':'查看'}}永久保存的完整校对依据</button><section v-if="showSnapshot"><h4>保存的字段映射</h4><dl class="saved-mapping"><div v-for="field in sourceFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{detail.previewSnapshot.mapping[field.key]||'未映射'}}</dd></div></dl><h4>保存的校对输入单元格</h4><p class="muted">以下为本批提交预览时保存的输入。上传原文件与解析原文在原始资料中另行保留。</p><div class="table-scroll raw-grid"><table><thead><tr><th>数据行</th><th v-for="column in savedColumns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(r,index) in detail.previewSnapshot.rawRows.slice((snapshotPage-1)*25,snapshotPage*25)" :key="index"><td>{{(snapshotPage-1)*25+index+1}}</td><td v-for="column in savedColumns" :key="column">{{r[column]??'—'}}</td></tr></tbody></table></div><h4>保存的逐行校对结果</h4><p class="muted">原始 {{detail.previewSnapshot.rows.length}} 行，未选行与异常行均保留。</p><div class="table-scroll"><table><thead><tr><th>原行</th><th>品名 / 规格</th><th>参考价</th><th>原校对状态 / 原问题</th><th>确认范围</th></tr></thead><tbody><tr v-for="r in detail.previewSnapshot.rows.slice((snapshotPage-1)*25,snapshotPage*25)" :key="r.rowNumber"><td>{{r.rowNumber}}</td><td>{{r.rawItemName}} / {{r.specification}}</td><td>{{r.referencePrice}}</td><td>{{({valid:'已匹配',unmatched:'未匹配',duplicate:'疑似重复',invalid:'异常'})[r.status]}}<small>{{r.errors.join('；')||'无格式问题'}}</small></td><td>{{detail.previewSnapshot.acceptedRowNumbers.includes(r.rowNumber)?'已确认':'未纳入'}}</td></tr></tbody></table></div><div class="pagination"><button :disabled="snapshotPage<=1" @click="snapshotPage--">上一页</button><span>{{snapshotPage}} / {{Math.max(1,Math.ceil(detail.previewSnapshot.rows.length/25))}}</span><button :disabled="snapshotPage*25>=detail.previewSnapshot.rows.length" @click="snapshotPage++">下一页</button></div></section><section class="source-file-panel"><h3>{{detail.sourceFileId?'本批关联原始文件：'+(detailSourceRef?.sourceFiles.find(f=>f.id===detail!.sourceFileId)?.fileName||'正在读取原文件名称'):'本批未关联原始文件'}}</h3><p class="muted">以下为该厂家原始资料，原件和更正版分别保存。</p><SourceFiles ref="detailSourceRef" :api="api" :user-id="userId" :reference="{kind:'manufacturer',manufacturerId:detail.manufacturerId}" readonly :locked="!!props.locked||busy" @busy-changed="childBusy=$event" @failure="emit('failure',$event)"/></section><form v-if="!readonly&&detail.status==='confirmed'" @submit.prevent="askVoid"><label>整批作废原因<textarea v-model="voidReason" maxlength="500" :disabled="writeLocked" @input="dirty=true"/></label><button :disabled="writeLocked">复核整批作废</button></form></template>
 <section v-if="review" class="review-panel" aria-label="来源批次提交复核"><h3>{{review==='confirm'?'确认新的来源批次':'整批作废来源批次'}}</h3><p v-if="review==='confirm'">{{manufacturerName(meta.manufacturerId)}} · {{meta.quotedAt}} · 厂家原批次号 {{meta.sourceBatchNo||'未填写'}} · 明确纳入 {{draft.selected.length}} 行；确认后不可覆盖、追加或删除。</p><p v-else>{{detail?.batchNo}} · 原因：{{voidReason}}。已确认行及原始资料继续保留。</p><p class="reference-notice">仅资料参考，不参与本次报价</p><label class="inline-check"><input v-model="ack" type="checkbox" :disabled="locked||pending"/>我已核对本次范围与依据</label><div class="button-row"><button class="primary" :disabled="locked||pending||!ack" @click="commit">确认提交</button><button :disabled="locked||pending" @click="review=null">返回核对</button></div></section>
 </section>
</template>
<style scoped>
.source-top{display:flex;justify-content:space-between;gap:20px;margin:22px 0}.source-top h2{margin-bottom:10px}.reference-notice{font-size:13px;color:#94662b;font-weight:600;margin:8px 0 12px}.source-filters{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:16px;align-items:end;margin:24px 0}.source-file-panel{border-top:1px solid #dce5df;border-bottom:1px solid #dce5df;padding:22px 0;margin:24px 0}.source-file-panel>label{max-width:600px;margin-top:20px}.manual-grid table{min-width:1260px}.manual-grid td{min-width:150px}.manual-grid td:first-child{min-width:45px}.manual-grid td:nth-child(4){min-width:220px}.manual-grid input{margin-bottom:6px}.source-batches table{font-size:12px}.source-batches td{overflow-wrap:anywhere}.raw-grid{max-height:380px}.raw-grid td{white-space:pre-wrap;min-width:130px}.saved-mapping{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:12px}.saved-mapping dt{color:#74837a;font-size:12px}.saved-mapping dd{margin:6px 0 14px;overflow-wrap:anywhere}.mapping-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:16px;margin:24px 0}.batch-preview,.review-panel{border-top:2px solid #215f46;margin:28px 0;padding:24px;background:#f5f8f3}.review-panel h3{margin-top:0}.review-panel p{line-height:1.8}.detail-heading{padding:20px 0}.source-batches form>button{margin-top:16px}.source-batches .form-grid>button{align-self:end}.source-batches .error{white-space:pre-line}.source-batches h3{font-size:16px}button{white-space:nowrap}@media(max-width:900px){.source-filters,.mapping-grid,.saved-mapping{grid-template-columns:1fr 1fr}.source-top{display:block}}
</style>
